$host=preg_replace('/[^a-zA-Z0-9.\-:\[\]]/','',$_SERVER['HTTP_HOST']??'localhost');$url=((!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http').'://'.$host.rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME'])),'/');
